import { aging_knockoff_workflow } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    bulkRejectDialog: Boolean,
    bulkitems: Object
  },
  data() {
    return {
      approvalComments: "",
      loading: false
    };
  },
  watch: {
    bulkRejectDialog: {
      async handler() {
        if (this.bulkRejectDialog == true) {}
      },
      immediate: true
    }
  },
  methods: {
    async validate_aprrovals() {
      const {
        valid
      } = await this.$refs.form1.validate();
      if (valid) {
        await this.bulk_reject_ids();
      }
    },
    async bulk_reject_ids() {
      this.loading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(aging_knockoff_workflow, {
          input: {
            user_email_id: data.user.user_email_id,
            initiate_id: this.bulkitems.initiate_id,
            comments: this.approvalComments
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.aging_knockoff_workflow);
        if (response.Status == "SUCCESS") {
          this.loading = false;
          this.$emit("successMsg", response.Message);
          this.$refs.form1.reset();
        } else {
          this.loading = false;

          // this.formCheck = false;
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
      }
    },
    close_dialog() {
      this.$emit("clicked", 0);
      this.$refs.form1.reset();
    }
  }
};
